// PlayerInfoUpdate is clientbound/minecraft:player_info_update (0x47), Java ClientboundPlayerInfoUpdatePacket.
type PlayerInfoUpdate struct {
	Actions types.EnumSet[types.PlayerInfoUpdateAction]
	Entries []PlayerInfoUpdateEntry // the parts of every entry are selected by the packet's action bits
}

// PacketID returns the clientbound id of PlayerInfoUpdate.
func (PlayerInfoUpdate) PacketID() packetid.ClientboundPacketID {
	return packetid.ClientboundPlayPlayerInfoUpdate
}

// PlayerInfoUpdateEntry is one entry of PlayerInfoUpdate (Java ClientboundPlayerInfoUpdatePacket$EntryBuilder); only the parts selected by the packet's Actions are read and written.
type PlayerInfoUpdateEntry struct {
	ProfileID   pk.UUID
	Name        pk.String                                                            // when AddPlayer
	Properties  types.List[user.Property, *user.Property]                            // when AddPlayer
	ChatSession pk.Option[types.RemoteChatSessionData, *types.RemoteChatSessionData] // when InitializeChat
	GameMode    types.GameType                                                       // when UpdateGameMode
	Listed      pk.Boolean                                                           // when UpdateListed
	Latency     pk.VarInt                                                            // when UpdateLatency
	DisplayName pk.Option[types.Text, *types.Text]                                   // when UpdateDisplayName
	ListOrder   pk.VarInt                                                            // when UpdateListOrder
	ShowHat     pk.Boolean                                                           // when UpdateHat
}

// fields lists the parts of e selected by guard, as one tuple to read or write.
func (e *PlayerInfoUpdateEntry) fields(guard types.EnumSet[types.PlayerInfoUpdateAction]) pk.Tuple {
	var t pk.Tuple
	t = append(t, &e.ProfileID)
	if guard.Has(types.PlayerInfoUpdateActionAddPlayer) {
		t = append(t, &e.Name, &e.Properties)
	}
	if guard.Has(types.PlayerInfoUpdateActionInitializeChat) {
		t = append(t, &e.ChatSession)
	}
	if guard.Has(types.PlayerInfoUpdateActionUpdateGameMode) {
		t = append(t, &e.GameMode)
	}
	if guard.Has(types.PlayerInfoUpdateActionUpdateListed) {
		t = append(t, &e.Listed)
	}
	if guard.Has(types.PlayerInfoUpdateActionUpdateLatency) {
		t = append(t, &e.Latency)
	}
	if guard.Has(types.PlayerInfoUpdateActionUpdateDisplayName) {
		t = append(t, &e.DisplayName)
	}
	if guard.Has(types.PlayerInfoUpdateActionUpdateListOrder) {
		t = append(t, &e.ListOrder)
	}
	if guard.Has(types.PlayerInfoUpdateActionUpdateHat) {
		t = append(t, &e.ShowHat)
	}
	return t
}

func (p *PlayerInfoUpdate) ReadFrom(r io.Reader) (n int64, err error) {
	var m int64
	if n, err = (pk.Tuple{&p.Actions}).ReadFrom(r); err != nil {
		return n, err
	}
	var count pk.VarInt
	if m, err = count.ReadFrom(r); err != nil {
		return n + m, err
	}
	n += m
	p.Entries = make([]PlayerInfoUpdateEntry, int(count))
	for i := range p.Entries {
		if m, err = p.Entries[i].fields(p.Actions).ReadFrom(r); err != nil {
			return n + m, err
		}
		n += m
	}
	return n, nil
}

func (p PlayerInfoUpdate) WriteTo(w io.Writer) (n int64, err error) {
	var m int64
	if n, err = (pk.Tuple{p.Actions}).WriteTo(w); err != nil {
		return n, err
	}
	if m, err = pk.VarInt(len(p.Entries)).WriteTo(w); err != nil {
		return n + m, err
	}
	n += m
	for i := range p.Entries {
		if m, err = p.Entries[i].fields(p.Actions).WriteTo(w); err != nil {
			return n + m, err
		}
		n += m
	}
	return n, nil
}

