// StopSound is clientbound/minecraft:stop_sound (0x79), Java ClientboundStopSoundPacket.
type StopSound struct {
	Flags  pk.Byte
	Source types.SoundSource
	Name   pk.Identifier
}

// PacketID returns the clientbound id of StopSound.
func (StopSound) PacketID() packetid.ClientboundPacketID { return packetid.ClientboundPlayStopSound }

func (p *StopSound) ReadFrom(r io.Reader) (n int64, err error) {
	var m int64
	m, err = pk.Tuple{&p.Flags}.ReadFrom(r)
	n += m
	if err != nil {
		return n, err
	}
	if p.Flags&1 != 0 {
		m, err = pk.Tuple{&p.Source}.ReadFrom(r)
		n += m
		if err != nil {
			return n, err
		}
	}
	if p.Flags&2 != 0 {
		m, err = pk.Tuple{&p.Name}.ReadFrom(r)
		n += m
		if err != nil {
			return n, err
		}
	}
	return n, nil
}

func (p StopSound) WriteTo(w io.Writer) (n int64, err error) {
	var m int64
	m, err = pk.Tuple{p.Flags}.WriteTo(w)
	n += m
	if err != nil {
		return n, err
	}
	if p.Flags&1 != 0 {
		m, err = pk.Tuple{p.Source}.WriteTo(w)
		n += m
		if err != nil {
			return n, err
		}
	}
	if p.Flags&2 != 0 {
		m, err = pk.Tuple{p.Name}.WriteTo(w)
		n += m
		if err != nil {
			return n, err
		}
	}
	return n, nil
}

